import sys
def ins(path, anchor, text, after=True):
    b=open(path,'rb').read().decode('utf-8')
    crlf='\r\n' in b
    a=anchor.replace('\n','\r\n') if crlf else anchor
    t=text.replace('\n','\r\n') if crlf else text
    assert b.count(a)==1,(path,anchor,b.count(a))
    b=b.replace(a,a+t if after else t+a)
    open(path,'wb').write(b.encode('utf-8'))

